 declare job public.product_image_cleanup; reason text;
begin
  if not public.is_admin() then raise exception 'admin_required'; end if;
  perform pg_advisory_xact_lock(hashtextextended('zhino-image-references',0));
  select * into job from public.product_image_cleanup where storage_path=p_path for update;
  if not found or job.claim_id is distinct from p_claim_id then return false; end if;
  if job.completed_at is not null then return true; end if;
  if job.lease_until is null or job.lease_until<=clock_timestamp() then return false; end if;
  if public.product_image_path_referenced(p_path) then reason := 'still_referenced';
  elsif exists(select 1 from storage.objects where bucket_id='product-images' and name=p_path) then reason := 'object_present';
  elsif p_storage_confirmed is distinct from true then reason := 'storage_unconfirmed';
  end if;
  if reason is not null then
    update public.product_image_cleanup set lease_until=null,last_error_code=reason,
      next_attempt_at=clock_timestamp()+make_interval(secs=>least(3600,5*power(2,least(job.attempt_count,10)))::integer)
      where storage_path=p_path;
    return false;
  end if;
  update public.product_image_cleanup set completed_at=clock_timestamp(),lease_until=null,last_error_code=null
    where storage_path=p_path;
  return true;
end

 begin
  if not public.is_admin() then raise exception 'admin_required'; end if;
  return 3;
end
